DROP TABLE IF EXISTS `master_adventures`;

/*!40101 SET @saved_cs_client     = @@character_set_client */;

/*!50503 SET character_set_client = utf8mb4 */;

CREATE TABLE `master_adventures` (

  `id` int NOT NULL,

  `type` int NOT NULL DEFAULT '1',

  `chapter` int NOT NULL DEFAULT '1',

  `stage` int NOT NULL DEFAULT '1',

  `stage_label` int NOT NULL DEFAULT '0',

  `energy_cost` int NOT NULL DEFAULT '5',

  `bg` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `enemy` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `enemy_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `exp` int NOT NULL DEFAULT '0',

  `rxp` int NOT NULL DEFAULT '0',

  `silver` int NOT NULL DEFAULT '0',

  `first_item` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `item_group` int NOT NULL DEFAULT '0',

  PRIMARY KEY (`id`)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

