INSERT INTO `master_buildings` VALUES (1,'Ninja Hut','homeBtn01','A room that used for recruiting ninjas. 10-combo capture will definitely catch ninja Class-A or higher.','<silver|2000>','60|5|1440','3|8|13|18|23|28|33|38|43|48','<silver|30000><gold|298><gold|2980>'),(2,'Ninjutsu School','homeBtn02','The road that cannot be avoided if you want to get the qualification of ninja. You can practice Ninjutsu and Vitality skill.','<silver|2000>','60|5','1|6|11|16|21|26|31|36|41|46','<silver|30000><gold|50>'),(3,'Ramen Restaurant','homeBtn03','The most popular ramen house of the ninja world. It’s not bad to rob occasionally.','<silver|2000>','60|5|1440','5|10|15|20|25|30|35|40|45|50',''),(4,'Whack A Ninja','','','','5','1','<gold|50>'),(5,'Summon School','homeBtn05','Orochimaru will teach you the summon skill personally.','<silver|4000>','120|5','7|12|17|22|27|32|37|42|47|52','<gold|98><gold|298>'),(6,'Hot Spring','homeBtn06','Take a bath in hot spring is necessary if you want to level up fast.','<silver|4000>','120|480|480','13|18|23|28|33|38|43|48|53|58','<silver|1000><gold|50>'),(7,'Arena','homeBtn07','The place where all skillful ninja want to go to. Rewards are sent according to rankings daily.','<silver|15000>','480','24|29|34|39|44|49|54|59|64|69',''),(8,'Laboratory','','','','','4','<gold|0><gold|5><gold|10><gold|30><gold|100><gold|200><gold|500><gold|1000>'),(9,'Senior ninja Trial','homeBtn09','A required course of senior ninja. Can obtain various rare materials.','<silver|8000>','240','16|21|26|31|36|41|46|51|56|61',''),(10,'Tailed Beast Altar','homeBtn10','Collect tailed beast chakra and infuse tailed beast skills to ninja.','<silver|15000>','480','20|25|30|35|40|45|50|55|60|65',''),(11,'Reward Quests','','','','0|30','1','<gold|50>'),(12,'Shadow Ninja Hall','homeBtn12','Team up to challenge legendary ninjas and recruit them to make them fight for you.','<silver|8000>','240','10|15|20|25|30|35|40|45|50|55','<gold|9>'),(13,'Anger of the Tailed Beast','','','','0|5','20','<gold|20>'),(14,'Battleground','homeBtn14','Show your real strength to the ninja world and win the final victory of the team battle.','<silver|15000>','480','25|30|35|40|45|50|55|60|65|70',''),(15,'Kage Ninja Hall','homeBtn15','Team up to challenge Kage level ninjas and recruit them to make them fight for you.','<silver|15000>','480','30|35|40|45|50|55|60|65|70|75','<gold|20>'),(16,'God Shinobi Tower','homeBtn16','Challenge the legendary top ninja to obtain precious materials for crafting equipment','<silver|15000>','480','35|40|45|50|55|60|65|70|75|80',''),(17,'Special Claw Crane','homeBtn17','There is a higher probability of capturing special ninjas.','<silver|8000>','240','15|20|25|30|35|40|45|50|55|60','<gold|298><gold|2980>');

