--

-- Table structure for table `master_jutsus`

--



DROP TABLE IF EXISTS `master_jutsus`;

/*!40101 SET @saved_cs_client     = @@character_set_client */;

/*!50503 SET character_set_client = utf8mb4 */;

CREATE TABLE `master_jutsus` (

  `id` int NOT NULL,

  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,

  `description` text COLLATE utf8mb4_unicode_ci,

  `desc_dmg` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `desc_turn` int NOT NULL DEFAULT '0',

  `probability` int NOT NULL DEFAULT '20',

  `turn_limit` int NOT NULL DEFAULT '0',

  `when_trigger` int NOT NULL DEFAULT '2',

  `quality` int NOT NULL DEFAULT '1',

  `grade` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'D',

  `category` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Ninjutsu',

  `act_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `alter_target` text COLLATE utf8mb4_unicode_ci,

  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `chakra_type` int NOT NULL DEFAULT '0',

  `element` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'None',

  `timeline_ready` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `timeline_run` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `timeline_hit` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `effect_ready` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `effect_run` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `effect_b` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `refine_cost` int NOT NULL DEFAULT '0',

  `trigger_rate` decimal(4,2) NOT NULL DEFAULT '0.30',

  `damage_multiplier` decimal(4,2) NOT NULL DEFAULT '1.50',

  `effect_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',

  `effect_value` int NOT NULL DEFAULT '0',

  PRIMARY KEY (`id`)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*!40101 SET character_set_client = @saved_cs_client */;



