--

-- Table structure for table `master_ninjas`

--



DROP TABLE IF EXISTS `master_ninjas`;

/*!40101 SET @saved_cs_client     = @@character_set_client */;

/*!50503 SET character_set_client = utf8mb4 */;

CREATE TABLE `master_ninjas` (

  `id` int NOT NULL,

  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,

  `xmlfile` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `quality` int NOT NULL DEFAULT '1',

  `grade` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'D',

  `chakra_type` int NOT NULL DEFAULT '0',

  `element` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'None',

  `base_hp` int NOT NULL DEFAULT '100',

  `base_atk` int NOT NULL DEFAULT '20',

  `base_def` int NOT NULL DEFAULT '15',

  `base_speed` int NOT NULL DEFAULT '20',

  `special_jutsu_id` int NOT NULL DEFAULT '0',

  `learnable_jutsus` text COLLATE utf8mb4_unicode_ci,

  `pos_top` int NOT NULL DEFAULT '0',

  `pos_bottom` int NOT NULL DEFAULT '0',

  `pos_left` int NOT NULL DEFAULT '0',

  `pos_right` int NOT NULL DEFAULT '0',

  `home_bg` int NOT NULL DEFAULT '1',

  `description` text COLLATE utf8mb4_unicode_ci,

  `gacha_available` tinyint NOT NULL DEFAULT '1',

  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,

  `title` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Shinobi',

  PRIMARY KEY (`id`)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*!40101 SET character_set_client = @saved_cs_client */;



