INSERT INTO `master_ninjas` VALUES (1,'Konohamaru','muyewan',1,'D',1,'Fire',291,57,57,57,1149,'1143|1151|1149|1099',4,3,2,3,1,'3rd Hokage\'s grandson and Naruto\'s follower, who has learn only one move: Sexy Jutsu.',1,'muyewan.png','D-Rank Shinobi'),(2,'Mizuki','shuimu',1,'D',2,'Wind',297,54,60,54,1015,'1015|1144|1004|1035',4,1,2,2,1,'The traitor of the Hidden Leaf, who intended to seize Book of Seal. She seemed to know nothing about it.',1,'shuimu.png','D-Rank Shinobi'),(3,'Misthide Guard','wuyinshouwei',1,'D',5,'Water',285,57,57,57,1086,'1086|1143|1035|1094',2,4,1,2,3,'A Mist Ninja; as a saying goes, \"Those who don\'t know Ninjutsus aren\'t good programmer apes\", so his unique skill is to write codes with hands and feet simultaneously.',1,'wuyinshouwei.png','D-Rank Shinobi'),(4,'Misthide Sentry','wuyinshaobing',1,'D',5,'Water',294,54,60,54,1143,'1143|1144|1016|1099',3,2,3,1,3,'A Mist Ninja, a Fujoshi liking disclosing secrets and gossips; the only thing in her life is to read BL cartoons and then fall into sexual fantasy.',1,'wuyinshaobing.png','D-Rank Shinobi'),(5,'Sandhide Guard','shayinshouwei',1,'D',2,'Wind',294,54,60,54,1086,'1086|1144|1004|1094',3,2,2,1,2,'A ninja from Sand Kingdom, a Fudanshi with two lovely eyes pretending to be young and liking touching ass gently while smiling and often having a conversation with male ninja subordinates in the small room.',1,'shayinshouwei.png','D-Rank Shinobi'),(6,'Sandhide Sentry','shayinshaobing',1,'D',2,'Wind',285,57,57,57,1035,'1035|1099|1004|1016',3,4,1,3,2,'A ninja from Sand Kingdom, an irritable woman controlled tightly by her husband without any freedom. She is good at causing normal male ninja to become gays.',1,'shayinshaobing.png','D-Rank Shinobi'),(7,'Omoi','aomoyi',1,'D',3,'Lightning',282,57,57,57,1015,'1015|1004|1143|1094',4,4,1,2,4,'A ninja from Thunder Kingdom, one of Killer B\'s disciples, irritable, flat-chested and argumentative.',1,'aomoyi.png','D-Rank Shinobi'),(8,'Karui','karuyi',1,'D',3,'Lightning',294,60,60,60,1015,'1015|1144|1016|1093',4,1,3,3,4,'A ninja from Thunder Kingdom, one of Killer B\'s disciples and eating a lollipop every day to receive trainings secretly…',1,'karuyi.png','D-Rank Shinobi'),(9,'Konoha Guard','muyeshouwei',1,'D',1,'Fire',291,60,60,63,1007,'1143|1099|1085|1007',3,4,4,1,1,'Watashi wa Simida - who came from South Korea and now lives in the Hidden Leaf Village, dreaming of becoming a popular actor like Kim Soo Hyun.',1,'muyeshouwei.png','D-Rank Shinobi'),(10,'Konoha Sentry','muyeshaobing',1,'D',1,'Fire',309,57,63,57,1149,'1149|1143|1094|1016',3,2,1,3,1,'A ninja from Fire Kingdom, gentle externally but amorous internally who always pushes his glasses 8 seconds ahead of others each time he hears an obscene story.',1,'muyeshaobing.png','D-Rank Shinobi'),(11,'Flameplate Brigand','chitongkai',1,'D',4,'Earth',306,60,60,60,1086,'1086|1155|1092|1099',3,4,1,2,1,'A Sound Ninja absorbing Chakra with his palm, a loser who can\'t find his existence significance.',1,'chitongkai.png','D-Rank Shinobi'),(12,'Yoroi','sakedeng',1,'D',4,'Earth',291,63,57,63,1149,'1149|1144|1016|1099',2,3,1,4,1,'A Sound Ninja with the hole on his hand to create ultrasonic waves, seemingly without blood relationship with bats.',1,'sakedeng.png','D-Rank Shinobi'),(13,'Tsurugi Misumi','jianmeicheng',1,'D',5,'Water',300,60,60,60,1086,'1086|1144|1004|1094',4,1,2,3,1,'A Sound Ninja with dislocated joints to make him soft, whose pet phrase is: don\'t disregard me because I\'m soft.',1,'jianmeicheng.png','D-Rank Shinobi'),(14,'Kimada','tuosizhen',1,'D',3,'Lightning',297,60,60,60,1035,'1035|1143|1004|1016',3,2,2,4,1,'A Sound Ninja using sound to directly attack the eardrum, adept at scheming, bullying the weak and swathed in bandages due to facial mutilations.',1,'tuosizhen.png','D-Rank Shinobi'),(15,'Anbu Guard','anbu1',1,'D',4,'Earth',312,57,63,57,1015,'1015|1004|1149|1085',3,1,2,2,1,'A Ninja from Root of the Hidden Leaf, famous for indifference except for secret assignments.',1,'anbu1.png','D-Rank Shinobi'),(16,'Anbu Sentry','anbu2',1,'D',4,'Earth',309,57,63,57,1015,'1015|1144|1016|1155',4,2,2,1,1,'A Ninja from Root of the Hidden Leaf, who wears a mask to conceal his identity. Actually he\'s a transvestism.',1,'anbu2.png','D-Rank Shinobi'),(17,'Naruto','mingren',2,'C',2,'Wind',389,64,64,64,1092,'1092|1125|1098|1149|1151|1117',4,3,1,3,1,'The guy ranking the last place with Nine Tails sealed inside, liking Ramen and making troubles. He likes Sakura but appears to be more persistent about Sasuke. Founder of Sexy Jutsu.',1,'mingren.png','C-Rank Shinobi'),(18,'Sakura','xiaoying',2,'C',5,'Water',400,62,67,62,1003,'1003|1004|1016|1099|1155',2,1,4,2,1,'A violent girl going crazy for Sasuke, good at Medic Ninjutsu, later attracted by Naruto and finally become a woman.',1,'xiaoying.png','C-Rank Shinobi'),(19,'Ino','jingye',2,'C',5,'Water',420,64,70,64,1016,'1016|1086|1144|1143',2,1,3,3,1,'A close friend of Sakura\'s, being jealous because she also likes Sasuke. She is good at using Mind Transfer Jutsu.',1,'jingye.png','C-Rank Shinobi'),(20,'Tenten','tiantian',2,'C',3,'Lightning',386,70,64,70,1007,'1086|1007|1131|1092',4,2,2,1,1,'A girl with strong hidden weapon skills, a little simple and naïve, often playing the peacemaker.',1,'tiantian.png','C-Rank Shinobi'),(21,'Choji','dingci',2,'C',3,'Lightning',400,62,67,62,1145,'1145|1086|1101|1092',3,3,3,2,1,'A well-developed fatso liking eating, who can use Expansion Jutsu to enlarge himself. He is cowardly but very kind.',1,'dingci.png','C-Rank Shinobi'),(22,'Kiba Inuzuka','quanzhongya',2,'C',4,'Earth',409,67,67,67,1112,'1107|1112|1111|1092',2,1,1,2,1,'He can fuse with his dog Akamaru. Tenten exhorts the dog while supporting it: hi, don\'t pee on my head.',1,'quanzhongya.png','C-Rank Shinobi'),(23,'Shino','zhinai',2,'C',4,'Earth',403,67,67,67,1085,'1015|1085|1113|1144',3,2,2,3,1,'He is almost mute except for \"Ur!\" and \"Ur?\", and often plays with various insects. Nobody sees what he is like after removing sunglasses.',1,'zhinai.png','C-Rank Shinobi'),(24,'Hinata','chutian',2,'C',1,'Fire',400,73,67,73,1005,'1084|1005|1011|1012|1006',4,2,2,2,1,'Young madam of Main House of Hyuga Clan with Byakugan, highly introverted and shy. She may blush and faint each time she sees Naruto.',1,'chutian.png','C-Rank Shinobi'),(25,'Nenji','ningci',2,'C',1,'Fire',403,73,67,73,1011,'1084|1005|1011|1012|1006',4,2,1,3,1,'An arrogant genius of Branch House of Hyuga Clan with Byakugan. He is Hinata\'s elder brother, a young cynic and later curing his psychic trauma.',1,'ningci.png','C-Rank Shinobi'),(26,'Lee','xiaoli',2,'C',1,'Fire',428,70,70,70,1009,'1086|1092|1099|1101|1009|1010|1098',1,2,1,2,1,'A simple, ardent boy with heavy eyebrow and a watermelon skin hairstyle. He is capable of vitality skills only but highly strong through various self-torture trainings.',1,'xiaoli.png','C-Rank Shinobi'),(27,'Sasuke','zuozhu',2,'C',3,'Lightning',420,70,70,70,1035,'1007|1035|1097|1101|1090|1025',4,2,3,1,1,'A genius of Uchiha Clan with Sharingan, favored by countless girls as a cool and indifferent boy; However, his first kiss was given to Naruto.',1,'zuozhu.png','C-Rank Shinobi'),(28,'Shikamaru','luwan',2,'C',4,'Earth',420,70,70,70,1104,'1104|1154|1083|1086',1,4,2,3,1,'He possesses an IQ of 200, but is sluggish and afraid of troubles. Despite his moderate Shadow Ninjutsu, he may deal with anyone with his tactics.',1,'luwan.png','C-Rank Shinobi'),(29,'Shizune','jingyin',2,'C',5,'Water',417,70,70,70,1004,'1004|1016|1144|1086',3,2,4,3,1,'Tsunade\'s follower and housekeeper, a Medic Ninja. She is always holding a pig named Tonton every day to store backup grain.',1,'jingyin.png','C-Rank Shinobi'),(30,'Iruka','yiluka',2,'C',1,'Fire',420,76,70,76,1086,'1098|1086|1143|1003',3,1,2,4,1,'An excellent teacher in the Hidden Leaf Village, who likes Naruto in every aspect and actively motivates his student by inviting him for Ramen.',1,'yiluka.png','C-Rank Shinobi'),(31,'Temari','shouju',2,'C',2,'Wind',428,76,70,76,1133,'1085|1086|1133|1131',3,3,4,2,2,'1st daughter of 4th Kazekage nicknamed Princess Iron Fan. Her fan may generate wind and sand, then darken the heaven and earth and finally wipe out all present people. She has a complicated relationship with Shikamaru.',1,'shouju.png','C-Rank Shinobi'),(32,'Kankuro','kanjiulang',2,'C',2,'Wind',442,73,73,73,1027,'1027|1133|1015|1144',2,3,4,4,2,'2nd son of 4th Kazekage, liking using inflated…oh, no, puppet dolls. Despite a little kinky tattoos on his face. He\'s also a good boy.',1,'kanjiulang.png','C-Rank Shinobi'),(33,'Ebisu','yibixi',3,'B',3,'Lightning',545,78,78,78,1016,'1016|1090|1086|1101|1153',2,1,2,1,1,'A tyrannism in the Hidden Leaf Village specialized in interrogation, who likes ruining captives spiritually especially with his kurbash and candles.',1,'yibixi.png','B-Rank Shinobi'),(34,'Ibiki','huibisi',3,'B',1,'Fire',559,76,81,76,1007,'1007|1131|1086|1143',3,1,4,3,1,'Private teacher of Konohamaru, delivering various ordered instructions externally but actually nicknamed Sex Maniac. Very fond of being treated by Sexy Jutsu.',1,'huibisi.png','B-Rank Shinobi'),(35,'Gekkou Hayate','yueguangjifeng',3,'B',2,'Wind',589,78,84,78,1106,'1092|1106|1098|1107|1153',4,2,4,1,1,'Featuring a weak body and dark eye circles, nobody knows what this ninja from the Hidden Leaf does at night…',1,'yueguangjifeng.png','B-Rank Shinobi'),(36,'Aoba Yamashiro','shanchengqingye',3,'B',1,'Fire',578,78,84,78,1098,'1092|1090|1086|1101|1098',2,2,2,1,1,'A normal ninja from the Hidden Leaf lacking sense of existence, acting as girls\' backup boyfriend and later degenerated into a lifting jack.',1,'shanchengqingye.png','B-Rank Shinobi'),(37,'Raido Ashinami','bingzuleitong',3,'B',2,'Wind',556,84,78,84,1099,'1035|1099|1107|1143',4,2,3,3,1,'A meticulous ninja from the Hidden Leaf with scars on the face, who is saving money for a beauty surgery.',1,'bingzuleitong.png','B-Rank Shinobi'),(38,'Genma Shiranui','buzhihuoxuanjian',3,'B',4,'Earth',562,81,81,81,1097,'1012|1097|1145|1106|1154',1,4,1,3,1,'A ninja from the Hidden Leaf liking biting a toothpick and pretending to be cool, who didn\'t realize he wouldn\'t have any girlfriend by this.',1,'buzhihuoxuanjian.png','B-Rank Shinobi'),(39,'Anko Mitarashi','hongdou',3,'B',1,'Fire',564,81,81,81,1016,'1016|1099|1086|1090',3,1,4,1,1,'Orochimaru\'s favorite disciple, a sassy girl from the Hidden Leaf. She is always regards his master with invisible affection.',1,'hongdou.png','B-Rank Shinobi'),(40,'Gaara','woailuo',3,'B',4,'Earth',599,81,86,81,1133,'1027|1133|1052|1054|1053|1014',2,2,4,1,2,'Youngest son with panda eyes of 4th Kazekage with One Tail sealed inside, who was tortured much in childhood. He became cool and indifferent after growing up and later was touched by Naruto.',1,'woailuo.png','B-Rank Shinobi'),(41,'Zabuza','zaibuzhan',3,'B',5,'Water',572,86,81,86,1018,'1018|1031|1106|1030|1135|1035',2,4,2,1,3,'Mist Ninja, One of Seven Swordman and his nicknamed is Demon. He is finally realized his deep love with Haku at the time of his death.',1,'zaibuzhan.png','B-Rank Shinobi'),(42,'Haku','bai',3,'B',5,'Water',599,81,86,81,1019,'1016|1019|1020|1018|1135|1031',4,1,1,4,3,'He has Ice Bloodline Limit, appears to be a little masochistic. He is gentler and more beautiful than women and regards Zabuza with deep affection by sacrificing his own life.',1,'bai.png','B-Rank Shinobi'),(43,'Kidomaru','guitongwan',3,'B',2,'Wind',602,81,86,81,1015,'1015|1131|1143|1019',3,3,2,4,1,'A Sound Ninja who has become a spider man after eating too much KLone Food. His spider silks are used in the fight or the textile factory.',1,'guitongwan.png','B-Rank Shinobi'),(44,'Tayuya','duoyouye',3,'B',3,'Lightning',570,86,81,86,1007,'1007|1086|1101|1135',3,3,1,1,1,'The only girl among Sound Ninjas, who couldn\'t blow her bamboo pipe instrument skillfully and then changed to a flute. She can use her melodies to manipulate three demons.',1,'duoyouye.png','B-Rank Shinobi'),(45,'Sakon and Ukon','zuojinyoujin',3,'B',1,'Fire',624,84,89,84,1016,'1016|1086|1099|1143',4,3,2,3,1,'Products of fused Sound Ninja brothers, occasionally separated or fused to have great fun.',1,'zuojinyoujin.png','B-Rank Shinobi'),(46,'Jirobo','cilangfang',3,'B',4,'Earth',618,84,89,84,1145,'1099|1145|1144|1106',2,3,2,3,1,'A fatso among Sound Ninjas who likes imprisoning someone in Earthen Prison to absorb Chakra and looks like a reincarnated fat bone spirit.',1,'cilangfang.png','B-Rank Shinobi'),(47,'Kimimaro','junmalv',3,'B',4,'Earth',605,86,86,86,1022,'1027|1021|1022|1107',1,2,1,2,1,'He possesses Bone Bloodline Limit and can pull all his bones out of his body freely. His worships and obsesses about Orochimaru so deeply, reaching upper limit of gay love.',1,'junmalv.png','B-Rank Shinobi'),(48,'Sai','zuojing',3,'B',3,'Lightning',605,86,86,86,1144,'1104|1144|1092|1101',3,4,2,1,1,'An ink and wash artist in Root of the Hidden Leaf without any EQ. Later his brain developed and changed from compliance to independent thinking.',1,'zuojing.png','B-Rank Shinobi'),(49,'Suigetsu','shuiyue',3,'B',5,'Water',591,89,84,89,1031,'1017|1018|1106|1031|1019',2,2,4,1,3,'Mist Ninja who can liquefy his body. It\'s very convenient for him to enter female bath house. He likes collecting blades and disclosing secrets.',1,'shuiyue.png','B-Rank Shinobi'),(50,'Karin','xianglin',3,'B',3,'Lightning',637,86,92,86,1004,'1004|1086|1016|1015',1,3,2,3,1,'A girl deeply attracted by Sasuke, who appears to be masochistic. She may feel happy when someone bites her due to her special physical constitution. Thus she\'s filled with bite marks.',1,'xianglin.png','B-Rank Shinobi'),(51,'Jugo','zhongwu',3,'B',2,'Wind',602,92,86,92,1099,'1085|1099|1131|1086',1,2,2,1,1,'A big boy with dual personality whose internal content may be used to refine Cursed Seal Essence. Generally he\'s kind and cowardly, but he\'ll be daring once he gets irritated.',1,'zhongwu.png','B-Rank Shinobi'),(52,'Kabuto','dou',3,'B',5,'Water',605,92,86,92,1015,'1015|1004|114