--

-- Table structure for table `master_role_groups`

--



DROP TABLE IF EXISTS `master_role_groups`;

/*!40101 SET @saved_cs_client     = @@character_set_client */;

/*!50503 SET character_set_client = utf8mb4 */;

CREATE TABLE `master_role_groups` (

  `id` int NOT NULL,

  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,

  `description` text COLLATE utf8mb4_unicode_ci,

  `roles` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,

  `alter_self` text COLLATE utf8mb4_unicode_ci,

  `skill_id` int NOT NULL DEFAULT '0',

  PRIMARY KEY (`id`)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*!40101 SET character_set_client = @saved_cs_client */;



